def transform(grid):
    bg_color = grid[0][0]

    # Create copy to work with
    result = [r[:] for r in grid]

    # Find first row that has foreground
    first_fg_row = None
    for r in range(len(grid)):
        if any(cell != bg_color for cell in grid[r]):
            first_fg_row = r
            break

    if first_fg_row is None:
        return grid

    # Reset that row to background
    result[first_fg_row][:] = [bg_color] * len(grid[0])

    # Find the bounding box of all foreground pixels
    min_r, max_r = first_fg_row, len(grid)
    min_c, max_c = len(grid[0]), -1

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != bg_color:
                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

    # Reset everything outside the bounding box to background
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if r < min_r or r > max_r or c < min_c or c > max_c:
                result[r][c] = bg_color

    return result
